"""★★ on-policy 响应重生成：用目标模型（vLLM chat API）逐条重生成响应。

官方 DFLASH/DSPARK 训练第一步（论文："responses generated by the target model"）。
输入: prompt-only jsonl {"id":..., "conversations":[{"role":"system|user","content":...}]}
输出: regen jsonl（原 system/user + 目标生成的 assistant 响应）
多轮: 每遇到 user 轮次就调一次目标生成，后轮 user 以上文生成的历史为上下文（逐轮 on-policy）。

采样参数（DeepSpec/论文默认）: temp 0.7 / top-p 0.8 / top-k 20 / max_tokens 4096 / non-thinking
用法:
  python regen_responses.py --endpoint http://127.0.0.1:8007/v1 \
      --input data/raw/perfectblend_10k_prompts.jsonl \
      --output data/regen/perfectblend_10k_regen.jsonl \
      --concurrency 16 [--limit 10000] [--resume]
"""
import argparse
import asyncio
import json
from pathlib import Path

import aiohttp

SAMPLE = {"temperature": 0.7, "top_p": 0.8, "top_k": 20, "max_tokens": 4096}


def load_rows(path: Path):
    for line in open(path, encoding="utf-8"):
        line = line.strip()
        if line:
            yield json.loads(line)


CHAT_URL = "/chat/completions"


async def regenerate_one(session, endpoint, rec, model, sem):
    """逐 user 轮次生成；system 只做上下文。返回 {id, conversations, error?}。"""
    async with sem:
        history = []  # 已确认的消息（system + 已生成的 assistant + user）
        for m in rec["conversations"]:
            if m["role"] == "system":
                history.append(m)
                continue
            if m["role"] != "user":
                continue  # 原 assistant 丢弃
            history.append(m)  # 当前 user
            payload = {"model": model, "messages": history, **SAMPLE}
            try:
                async with session.post(endpoint + CHAT_URL, json=payload) as resp:
                    if resp.status != 200:
                        body = await resp.text()
                        return {"id": rec.get("id"), "error": f"HTTP {resp.status}: {body[:200]}"}
                    data = await resp.json()
            except Exception as e:
                return {"id": rec.get("id"), "error": f"{type(e).__name__}: {str(e)[:200]}"}
            content = data["choices"][0]["message"]["content"]
            history.append({"role": "assistant", "content": content})
        return {"id": rec.get("id"), "conversations": history}


async def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--endpoint", default="http://127.0.0.1:8007/v1")
    ap.add_argument("--input", type=Path, required=True)
    ap.add_argument("--output", type=Path, required=True)
    ap.add_argument("--model", default="Qwen3.8-27B")
    ap.add_argument("--concurrency", type=int, default=16)
    ap.add_argument("--limit", type=int, default=None)
    ap.add_argument("--resume", action="store_true")
    args = ap.parse_args()

    args.output.parent.mkdir(parents=True, exist_ok=True)
    seen = set()
    if args.resume and args.output.exists():
        for line in open(args.output):
            try:
                seen.add(json.loads(line)["id"])
            except Exception:
                pass

    rows = list(load_rows(args.input))
    if args.limit is not None:
        rows = rows[: args.limit]

    sem = asyncio.Semaphore(args.concurrency)
    async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=300)) as session:
        with open(args.output, "a") as f:
            done = 0
            errors = 0
            for i in range(0, len(rows), args.concurrency):
                batch = rows[i : i + args.concurrency]
                results = await asyncio.gather(
                    *[regenerate_one(session, args.endpoint, r, args.model, sem) for r in batch]
                )
                for r in results:
                    if "error" in r:
                        errors += 1
                        print(f"  ERR {r['id']}: {r['error']}")
                    else:
                        f.write(json.dumps(r, ensure_ascii=False) + "\n")
                        done += 1
                f.flush()
                if (i // args.concurrency) % 20 == 0:
                    print(f"  ... {min(i + len(batch), len(rows))}/{len(rows)} (err={errors})")
    print(f"done: {done} ok, {errors} err -> {args.output}")


if __name__ == "__main__":
    asyncio.run(main())
